import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import HighchartsReact from 'highcharts-react-official';
import Highcharts from 'highcharts';
import { mcategories, source } from 'https://irpocket.com/0001/react_chart/data.js';
import './App.css';

const LineChart = () => {
  const [current, setCurrent] = useState('gyouseki');
  const [viewMode, setViewMode] = useState('graph');
  const [checkedItems, setCheckedItems] = useState(
    mcategories.reduce((acc, year) => {
      acc[year] = true;
      return acc;
    }, {})
  );

  const data = source[current].master;
  const indexes = source[current].indexes;

  const label = {
    enabled: false,
    rotation: -90,
    color: '#FFFFFF',
    align: 'right',
    x: 4,
    y: 10,
    style: {
      fontSize: '13px',
      fontFamily: '"Open Sans","Meiryo","Hiragino Kaku Gothic ProN",Helvetica,Arial,sans-serif'
    }
  };

  // フィルターされた年（チェックされてる年）
  const filteredYears = mcategories.filter(year => checkedItems[year]);

  // 表示用 series データを再構成
  const filteredSeries = indexes.map((idx, i) => ({
    type: idx.type,
    name: idx.name,
    dataLabels: label,
    data: data[i].filter((_, index) => checkedItems[mcategories[index]]),
    yAxis: idx.type === 'column' ? 0 : 1,
    color: idx.color,
    marker: { symbol: idx.symbol || null },
    visible: idx.visible,
    selected: idx.visible,
    dp: idx.dp
  }));

  const chartOptions = {
    chart: { type: 'column' },
    xAxis: {
      categories: filteredYears,
      labels: {
        rotation: 0,
        align: "center",
        style: {
          fontSize: "12px",
          fontFamily: '"Droid Sans", "ヒラギノ角ゴ ProN W3", "Hiragino Kaku Gothic ProN", メイリオ, Meiryo',
        },
      },
    },
    yAxis: [
      {
        title: { text: source[current].unit },
      },
      {
        title: { text: source[current].unit2 },
        opposite: true,
      }
    ],
    series: filteredSeries,
  };

  return (
    <div className="container">

      {/* 表示切り替え */}
      {viewMode === 'graph' ? (
          <div style={{ marginBottom: '1rem' }}>
            <button onClick={() => setViewMode('graph')}><img src="//www.magicalir.net/3843/chart/assets/images/button-graph-on_r2024.png" /></button>
            <button onClick={() => setViewMode('table')}><img src="//www.magicalir.net/3843/chart/assets/images/button-table_r2024.png" /></button>
          </div>
        ) : (
          <div style={{ marginBottom: '1rem' }}>
            <button onClick={() => setViewMode('graph')}><img src="//www.magicalir.net/3843/chart/assets/images/button-graph_r2024.png" /></button>
            <button onClick={() => setViewMode('table')}><img src="//www.magicalir.net/3843/chart/assets/images/button-table-on_r2024.png" /></button>
          </div>          
        )
      }

      {/* タブ切り替え */}
      <ul className="irpTag">
        {["gyouseki", "zaisei", "cashflow", "hitokabu", "kabuka"].map((key) => (
          <li
            key={key}
            className={key === current ? "active" : ""}
            onClick={() => setCurrent(key)}
          >
            {key === "gyouseki" && "業績状況"}
            {key === "zaisei" && "財政状態"}
            {key === "cashflow" && "キャッシュ・フロー"}
            {key === "hitokabu" && "1株当たり指標"}
            {key === "kabuka" && "株価収益性"}
          </li>
        ))}
      </ul>

      {viewMode === 'graph' ? (
        <HighchartsReact highcharts={Highcharts} options={chartOptions} />
      ) : (
        <TableView categories={filteredYears} series={filteredSeries} />
      )}

      <CheckboxList
        mcategories={mcategories}
        checkedItems={checkedItems}
        setCheckedItems={setCheckedItems}
      />

      <YearNaviButtons mcategories={mcategories} setCheckedItems={setCheckedItems} />

    </div>
  );
};

// 年ナビ
const YearNaviButtons = ({ mcategories, setCheckedItems }) => {
  const handleClick = (years) => {
  setCheckedItems(prev => {
  const newState = { ...prev };
  const sorted = [...mcategories].sort().reverse(); // 新しい順
  const target = sorted.slice(0, years);
  mcategories.forEach(y => {
  newState[y] = target.includes(y);
  });
  return newState;
  });
  };


  return (
  <div className="btns">
  <input type="button" value="直近３年" onClick={() => handleClick(3)} />
  <input type="button" value="直近５年" onClick={() => handleClick(5)} />
  <input type="button" value="全選択" onClick={() => handleClick(mcategories.length)} />
  </div>
  );
};



// テーブル作成　（HTMLのレイアウトはここで調整する）
const TableView = ({ categories, series }) => (
  <table border="1" cellPadding="5" style={{ borderCollapse: 'collapse', width: '100%' }}>
    <thead>
      <tr>
        <th>項目</th>
        {categories.map((cat, idx) => (
          <th key={idx}>{cat}</th>
        ))}
      </tr>
    </thead>
    <tbody>
      {series.map((s, sIdx) => (
        <tr key={sIdx}>
          <td>{s.name}</td>
          {s.data.map((val, idx) => (
            <td key={idx}>{val}</td>
          ))}
        </tr>
      ))}
    </tbody>
  </table>
);

// チェックボックス実装
const CheckboxList = ({ mcategories, checkedItems, setCheckedItems }) => {
  const handleChange = (event) => {
    const { id, checked } = event.target;
    setCheckedItems(prev => ({
      ...prev,
      [id]: checked
    }));
  };

  return (
    <div>
      {mcategories.map(year => (
        <span key={year} style={{ marginRight: '8px' }}>
          <input
            type="checkbox"
            id={year}
            checked={checkedItems[year]}
            onChange={handleChange}
          />
          <label htmlFor={year}>{year}年</label>
        </span>
      ))}
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container);
root.render(<LineChart />);
